CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT 'CMI Student' CHECK (char_length(display_name) BETWEEN 1 AND 80), bio text NOT NULL DEFAULT '' CHECK (char_length(bio) <= 500));
GRANT SELECT ON public.profiles TO anon;
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "public author profiles" ON public.profiles FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "own profile create" ON public.profiles FOR INSERT TO authenticated WITH CHECK (id = auth.uid() AND public.has_role(auth.uid(), 'user'));
CREATE POLICY "own profile edit" ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
INSERT INTO public.profiles (id, display_name) SELECT u.id, COALESCE((SELECT r.author_name FROM public.resources r WHERE r.uploader_id=u.id ORDER BY r.created_at DESC LIMIT 1), 'CMI Student') FROM auth.users u;
CREATE FUNCTION public.create_archive_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id) VALUES(NEW.id) ON CONFLICT DO NOTHING; RETURN NEW; END; $$;
CREATE TRIGGER create_archive_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_archive_profile();
ALTER TABLE public.resources ADD COLUMN revision_number integer NOT NULL DEFAULT 0;
CREATE TABLE public.resource_updates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), resource_id uuid NOT NULL REFERENCES public.resources(id) ON DELETE CASCADE, uploader_id uuid NOT NULL, title text NOT NULL CHECK (char_length(title) BETWEEN 1 AND 150), description text, author_name text NOT NULL CHECK (char_length(author_name) BETWEEN 1 AND 80), academic_year text, course_id uuid NOT NULL REFERENCES public.courses(id), section text NOT NULL DEFAULT 'course' CHECK(section IN ('course','miscellaneous')), tags text[] NOT NULL DEFAULT '{}', kind public.resource_kind NOT NULL, file_path text, url text, base_version integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), created_at timestamptz NOT NULL DEFAULT now(), reviewed_at timestamptz);
GRANT SELECT, INSERT ON public.resource_updates TO authenticated;
GRANT ALL ON public.resource_updates TO service_role;
ALTER TABLE public.resource_updates ENABLE ROW LEVEL SECURITY;
CREATE POLICY "owner or moderator read updates" ON public.resource_updates FOR SELECT TO authenticated USING (uploader_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY "owner submits update" ON public.resource_updates FOR INSERT TO authenticated WITH CHECK (uploader_id=auth.uid() AND status='pending' AND EXISTS(SELECT 1 FROM public.resources r WHERE r.id=resource_id AND r.uploader_id=auth.uid()));
CREATE UNIQUE INDEX one_pending_resource_update ON public.resource_updates(resource_id) WHERE status='pending';
CREATE FUNCTION public.validate_resource_update() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.resources; BEGIN SELECT * INTO r FROM public.resources WHERE id=NEW.resource_id FOR UPDATE; IF NOT FOUND OR r.uploader_id IS DISTINCT FROM auth.uid() OR NEW.uploader_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'You can only update your own uploads'; END IF; IF NOT EXISTS(SELECT 1 FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL AND public.archive_email_allowed(email)) THEN RAISE EXCEPTION 'Verify your archive account first'; END IF; IF r.course_request_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.course_requests WHERE id=r.course_request_id AND status='pending') THEN RAISE EXCEPTION 'Wait for your course request to be reviewed first'; END IF; IF NEW.kind='link' THEN IF NEW.url IS NULL OR NEW.url !~ '^https?://' THEN RAISE EXCEPTION 'A valid HTTP link is required'; END IF; NEW.file_path=NULL; ELSE IF NEW.file_path IS NULL OR split_part(NEW.file_path,'/',1)<>NEW.uploader_id::text THEN RAISE EXCEPTION 'Use a file from your own uploads'; END IF; NEW.url=NULL; END IF; IF NOT EXISTS(SELECT 1 FROM public.courses c WHERE c.id=NEW.course_id AND ((NEW.section='miscellaneous' AND c.code='MISC') OR (NEW.section='course' AND c.code<>'MISC'))) THEN RAISE EXCEPTION 'Choose a valid course or miscellaneous section'; END IF; NEW.base_version=r.revision_number; NEW.status='pending'; NEW.reviewed_at=NULL; RETURN NEW; END; $$;
CREATE TRIGGER validate_resource_update BEFORE INSERT ON public.resource_updates FOR EACH ROW EXECUTE FUNCTION public.validate_resource_update();
CREATE FUNCTION public.bump_resource_revision() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.revision_number=OLD.revision_number+1; RETURN NEW; END; $$;
CREATE TRIGGER bump_resource_revision BEFORE UPDATE ON public.resources FOR EACH ROW EXECUTE FUNCTION public.bump_resource_revision();
CREATE FUNCTION public.review_resource_update(_id uuid, _approve boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u public.resource_updates; r public.resources; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Only verified moderators can review updates'; END IF; SELECT * INTO u FROM public.resource_updates WHERE id=_id FOR UPDATE; IF NOT FOUND OR u.status<>'pending' THEN RAISE EXCEPTION 'This update has already been reviewed'; END IF; SELECT * INTO r FROM public.resources WHERE id=u.resource_id FOR UPDATE; IF _approve THEN IF r.revision_number<>u.base_version THEN RAISE EXCEPTION 'The note changed after this update was submitted. Reject it and request a fresh update.'; END IF; UPDATE public.resources SET title=u.title, description=u.description, author_name=u.author_name, academic_year=u.academic_year, course_id=u.course_id, section=u.section, tags=u.tags, kind=u.kind, file_path=u.file_path, url=u.url, status='approved' WHERE id=u.resource_id; END IF; UPDATE public.resource_updates SET status=CASE WHEN _approve THEN 'approved' ELSE 'rejected' END, reviewed_at=now() WHERE id=_id; END; $$;
REVOKE ALL ON FUNCTION public.review_resource_update(uuid,boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.review_resource_update(uuid,boolean) TO authenticated;
ALTER PUBLICATION supabase_realtime ADD TABLE public.resource_updates;